const reservation = $input.first().json.body.reservation;

// -------- DATE -> "Thu, 17 Aug 2025" (ordem garantida)
const dateObj = new Date(reservation.date);

const dateParts = new Intl.DateTimeFormat('en-GB', {
  weekday: 'short',
  day: '2-digit',
  month: 'short',
  year: 'numeric',
}).formatToParts(dateObj);

const getPart = (type) => dateParts.find(p => p.type === type)?.value || '';

const formattedDate = `${getPart('weekday')}, ${getPart('day')} ${getPart('month')} ${getPart('year')}`;

// -------- TIME -> "9:00 PM"
let timeObj;
if (typeof reservation.time === 'string' && /^\d{1,2}:\d{2}(:\d{2})?$/.test(reservation.time)) {
  const [h, m] = reservation.time.split(':');
  timeObj = new Date(2000, 0, 1, Number(h), Number(m));
} else {
  timeObj = new Date(reservation.time);
}

const formattedTime = new Intl.DateTimeFormat('en-US', {
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
}).format(timeObj);

// -------- PROPOSED TIME -> "9:00 PM" (mesmo formato do TIME)
let proposedTimeObj;
if (typeof reservation.proposed_time === 'string' && /^\d{1,2}:\d{2}(:\d{2})?$/.test(reservation.proposed_time)) {
  const [h, m] = reservation.proposed_time.split(':');
  proposedTimeObj = new Date(2000, 0, 1, Number(h), Number(m));
} else {
  proposedTimeObj = new Date(reservation.proposed_time);
}

const formattedProposedTime = new Intl.DateTimeFormat('en-US', {
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
}).format(proposedTimeObj);

// -------- PEOPLE -> "1 guest" / "4 guests"
const people = Number(reservation.people);
const formattedPeople = `${people} ${people === 1 ? 'guest' : 'guests'}`;

// -------- DETAILS -> default "No details."
const formattedDetails =
  reservation.details && String(reservation.details).trim() !== ''
    ? String(reservation.details).trim()
    : 'No details.';

return [
  {
    json: {
      formattedDate,
      formattedTime,
      formattedProposedTime,
      formattedPeople,
      formattedDetails,
    },
  },
];

